insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('shokoladnyy-fondan', 'dessert', false, null, 20, 380, 4, 'medium',
   '{"ru":"Шоколадный фондан с жидким центром","en":"Chocolate fondant with a molten centre","ua":"Шоколадний фондан із рідким центром"}'::jsonb,
   '{"ru":"Маленькие шоколадные кексы с горячей тягучей серединкой, которая вытекает при разломе. Секрет — не передержать в духовке: снаружи корочка, внутри жидкий шоколад.","en":"Little chocolate cakes with a hot, gooey centre that flows out when you break them open. The secret is not to overbake — a set crust outside, molten chocolate within.","ua":"Маленькі шоколадні кекси з гарячою тягучою серединкою, що витікає при розломі. Секрет — не перетримати в духовці: зовні скоринка, всередині рідкий шоколад."}'::jsonb,
   '{"ru":["Тёмный шоколад — 100 г","Сливочное масло — 100 г","Яйца — 2 шт.","Сахар — 60 г","Мука — 40 г","Щепотка соли"],"en":["Dark chocolate — 100 g","Butter — 100 g","Eggs — 2","Sugar — 60 g","Flour — 40 g","A pinch of salt"],"ua":["Чорний шоколад — 100 г","Вершкове масло — 100 г","Яйця — 2 шт.","Цукор — 60 г","Борошно — 40 г","Дрібка солі"]}'::jsonb,
   '{"ru":["Растопите шоколад со сливочным маслом на водяной бане.","Взбейте яйца с сахаром до пышности и соедините с шоколадом.","Аккуратно вмешайте муку и соль до однородности.","Разлейте по смазанным формочкам и выпекайте при 200 °C 9–11 минут.","Совет: центр должен остаться подвижным — тогда фондан вытечет при разломе."],"en":["Melt the chocolate with the butter over a water bath.","Whisk the eggs with the sugar until fluffy and fold into the chocolate.","Gently stir in the flour and salt until smooth.","Pour into greased ramekins and bake at 200 °C for 9–11 minutes.","Tip: the centre should still wobble — that''s what makes it flow."],"ua":["Розтопіть шоколад із вершковим маслом на водяній бані.","Збийте яйця з цукром до пишності й з''єднайте з шоколадом.","Обережно вмішайте борошно й сіль до однорідності.","Розлийте по змащених формочках і випікайте за 200 °C 9–11 хвилин.","Порада: центр має лишитися рухливим — тоді фондан витече при розломі."]}'::jsonb,
   '{"ru":["десерт","шоколад","выпечка"],"en":["dessert","chocolate","baking"],"ua":["десерт","шоколад","випічка"]}'::jsonb)
on conflict (slug) do update set
  category = excluded.category,
  is_pp = excluded.is_pp,
  minutes = excluded.minutes,
  calories = excluded.calories,
  servings = excluded.servings,
  difficulty = excluded.difficulty,
  title = excluded.title,
  description = excluded.description,
  ingredients = excluded.ingredients,
  steps = excluded.steps,
  tags = excluded.tags;

insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('chizkeyk-bez-vypechki', 'dessert', false, null, 30, 340, 8, 'easy',
   '{"ru":"Чизкейк без выпечки","en":"No-bake cheesecake","ua":"Чизкейк без випікання"}'::jsonb,
   '{"ru":"Нежный сливочный чизкейк на песочной основе, который застывает в холодильнике — духовка не нужна. Готовится просто, а получается как из кондитерской.","en":"A silky cream-cheese cheesecake on a biscuit base that sets in the fridge — no oven needed. Simple to make, yet it tastes like it''s from a patisserie.","ua":"Ніжний вершковий чизкейк на пісочній основі, що застигає в холодильнику — духовка не потрібна. Готується просто, а виходить як із кондитерської."}'::jsonb,
   '{"ru":["Печенье песочное — 200 г","Сливочное масло — 90 г","Сливочный сыр — 400 г","Сливки 33% — 200 мл","Сахарная пудра — 80 г","Ванильный экстракт — 1 ч. л.","Желатин — 10 г"],"en":["Shortbread biscuits — 200 g","Butter — 90 g","Cream cheese — 400 g","Cream 33% — 200 ml","Icing sugar — 80 g","Vanilla extract — 1 tsp","Gelatin — 10 g"],"ua":["Пісочне печиво — 200 г","Вершкове масло — 90 г","Вершковий сир — 400 г","Вершки 33% — 200 мл","Цукрова пудра — 80 г","Ванільний екстракт — 1 ч. л.","Желатин — 10 г"]}'::jsonb,
   '{"ru":["Измельчите печенье, смешайте с растопленным маслом и утрамбуйте в форму.","Замочите желатин по инструкции и распустите, не кипятя.","Взбейте сливочный сыр с пудрой и ванилью, влейте желатин.","Отдельно взбейте сливки и аккуратно соедините с сырной массой.","Вылейте на основу и уберите в холодильник на 4 часа до застывания."],"en":["Crush the biscuits, mix with melted butter and press into a tin.","Soak the gelatin per the pack and dissolve it without boiling.","Beat the cream cheese with icing sugar and vanilla, then add the gelatin.","Whip the cream separately and fold gently into the cheese mixture.","Pour onto the base and chill for 4 hours until set."],"ua":["Подрібніть печиво, змішайте з розтопленим маслом і утрамбуйте у форму.","Замочіть желатин за інструкцією та розпустіть, не кип''ятячи.","Збийте вершковий сир із пудрою й ваніллю, влийте желатин.","Окремо збийте вершки й обережно з''єднайте із сирною масою.","Вилийте на основу й приберіть у холодильник на 4 години до застигання."]}'::jsonb,
   '{"ru":["десерт","чизкейк","без выпечки"],"en":["dessert","cheesecake","no-bake"],"ua":["десерт","чизкейк","без випікання"]}'::jsonb)
