  steps = excluded.steps,
  tags = excluded.tags;

insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('tiramisu-klassicheskiy', 'dessert', false, null, 30, 360, 6, 'medium',
   '{"ru":"Классический тирамису","en":"Classic tiramisu","ua":"Класичний тірамісу"}'::jsonb,
   '{"ru":"Итальянский десерт из печенья савоярди, пропитанного кофе, и воздушного крема на маскарпоне. Тает во рту, а сверху — щедрый слой какао.","en":"The Italian dessert of coffee-soaked savoiardi and an airy mascarpone cream. It melts in the mouth, under a generous dusting of cocoa.","ua":"Італійський десерт із печива савоярді, просоченого кавою, та повітряного крему на маскарпоне. Тане в роті, а зверху — щедрий шар какао."}'::jsonb,
   '{"ru":["Печенье савоярди — 200 г","Маскарпоне — 400 г","Яйца — 3 шт.","Сахар — 80 г","Крепкий кофе — 250 мл","Какао — для посыпки"],"en":["Savoiardi biscuits — 200 g","Mascarpone — 400 g","Eggs — 3","Sugar — 80 g","Strong coffee — 250 ml","Cocoa — for dusting"],"ua":["Печиво савоярді — 200 г","Маскарпоне — 400 г","Яйця — 3 шт.","Цукор — 80 г","Міцна кава — 250 мл","Какао — для посипання"]}'::jsonb,
   '{"ru":["Взбейте желтки с сахаром добела, вмешайте маскарпоне.","Отдельно взбейте белки до устойчивых пиков и аккуратно введите в крем.","Быстро обмакивайте савоярди в остывший кофе и выкладывайте слоем.","Покройте кремом, повторите слои и уберите в холодильник на 4–6 часов.","Перед подачей щедро посыпьте какао через сито."],"en":["Beat the yolks with sugar until pale, then stir in the mascarpone.","Whip the whites to stiff peaks and fold gently into the cream.","Quickly dip the savoiardi in cooled coffee and lay out a layer.","Cover with cream, repeat the layers and chill for 4–6 hours.","Before serving, dust generously with cocoa through a sieve."],"ua":["Збийте жовтки з цукром добіла, вмішайте маскарпоне.","Окремо збийте білки до стійких піків і обережно введіть у крем.","Швидко вмочайте савоярді в охолоджену каву й викладайте шаром.","Покрийте кремом, повторіть шари й приберіть у холодильник на 4–6 годин.","Перед подачею щедро посипте какао через сито."]}'::jsonb,
   '{"ru":["десерт","тирамису","кофе"],"en":["dessert","tiramisu","coffee"],"ua":["десерт","тірамісу","кава"]}'::jsonb)
