values
  ('ovsyanoe-pechenye', 'dessert', true, null, 25, 190, 6, 'easy',
   '{"ru":"Овсяное печенье без сахара","en":"Sugar-free oatmeal cookies","ua":"Вівсяне печиво без цукру"}'::jsonb,
   '{"ru":"Мягкое овсяное печенье на банане, без сахара и муки — полезный перекус к чаю. Готовится в одной миске за пять минут и печётся, пока закипает чайник.","en":"Soft banana oatmeal cookies with no sugar or flour — a wholesome snack with tea. One bowl, five minutes, and they bake while the kettle boils.","ua":"М''яке вівсяне печиво на банані, без цукру та борошна — корисний перекус до чаю. Готується в одній мисці за п''ять хвилин і печеться, поки закипає чайник."}'::jsonb,
   '{"ru":["Овсяные хлопья — 150 г","Банан спелый — 2 шт.","Изюм — 50 г","Орехи — 40 г","Корица — 0,5 ч. л.","Щепотка соли"],"en":["Rolled oats — 150 g","Ripe bananas — 2","Raisins — 50 g","Nuts — 40 g","Cinnamon — 0.5 tsp","A pinch of salt"],"ua":["Вівсяні пластівці — 150 г","Стиглий банан — 2 шт.","Родзинки — 50 г","Горіхи — 40 г","Кориця — 0,5 ч. л.","Дрібка солі"]}'::jsonb,
   '{"ru":["Разомните бананы вилкой в пюре.","Смешайте с хлопьями, изюмом, орехами, корицей и солью.","Дайте массе постоять 10 минут, чтобы хлопья набухли.","Выкладывайте ложкой на пергамент, формируя печенье.","Выпекайте при 180 °C 15–18 минут до румяности."],"en":["Mash the bananas with a fork into a purée.","Mix with the oats, raisins, nuts, cinnamon and salt.","Let the mixture rest 10 minutes so the oats swell.","Spoon onto parchment, shaping into cookies.","Bake at 180 °C for 15–18 minutes until golden."],"ua":["Розімніть банани виделкою в пюре.","Змішайте з пластівцями, родзинками, горіхами, корицею й сіллю.","Дайте масі постояти 10 хвилин, щоб пластівці набубнявіли.","Викладайте ложкою на пергамент, формуючи печиво.","Випікайте за 180 °C 15–18 хвилин до рум''яності."]}'::jsonb,
   '{"ru":["ПП","десерт","печенье","без сахара"],"en":["healthy","dessert","cookies","sugar-free"],"ua":["ПХ","десерт","печиво","без цукру"]}'::jsonb)
