insert into public.recipes
  (slug, category, is_pp, image, minutes, calories, servings, difficulty, title, description, ingredients, steps, tags)
values
  ('bananovyy-hleb', 'baking', false, null, 60, 280, 8, 'easy',
   '{"ru":"Банановый хлеб","en":"Banana bread","ua":"Банановий хліб"}'::jsonb,
   '{"ru":"Влажный ароматный кекс на спелых бананах — отличный способ пристроить потемневшие бананы. Простое тесто в одной миске и потрясающий аромат на всю кухню.","en":"A moist, fragrant loaf made with ripe bananas — the best way to use up ones that have gone brown. One-bowl batter and an aroma that fills the kitchen.","ua":"Вологий ароматний кекс на стиглих бананах — чудовий спосіб прилаштувати потемнілі банани. Просте тісто в одній мисці й приголомшливий аромат на всю кухню."}'::jsonb,
   '{"ru":["Банан спелый — 3 шт.","Мука — 200 г","Сахар — 100 г","Яйца — 2 шт.","Сливочное масло — 80 г","Разрыхлитель — 1 ч. л.","Щепотка соли","Грецкие орехи — 50 г"],"en":["Ripe bananas — 3","Flour — 200 g","Sugar — 100 g","Eggs — 2","Butter — 80 g","Baking powder — 1 tsp","A pinch of salt","Walnuts — 50 g"],"ua":["Стиглий банан — 3 шт.","Борошно — 200 г","Цукор — 100 г","Яйця — 2 шт.","Вершкове масло — 80 г","Розпушувач — 1 ч. л.","Дрібка солі","Волоські горіхи — 50 г"]}'::jsonb,
   '{"ru":["Разомните бананы, добавьте растопленное масло, сахар и яйца.","Всыпьте муку с разрыхлителем и солью, перемешайте до однородности.","Вмешайте рубленые орехи.","Вылейте тесто в форму для кекса, застеленную пергаментом.","Выпекайте при 175 °C около 45–50 минут до сухой шпажки."],"en":["Mash the bananas, add melted butter, sugar and eggs.","Stir in the flour with baking powder and salt until smooth.","Fold in the chopped walnuts.","Pour the batter into a parchment-lined loaf tin.","Bake at 175 °C for about 45–50 minutes until a skewer comes out clean."],"ua":["Розімніть банани, додайте розтоплене масло, цукор і яйця.","Всипте борошно з розпушувачем і сіллю, перемішайте до однорідності.","Вмішайте порубані горіхи.","Вилийте тісто у форму для кексу, застелену пергаментом.","Випікайте за 175 °C близько 45–50 хвилин до сухої шпажки."]}'::jsonb,
   '{"ru":["выпечка","банан","кекс"],"en":["baking","banana","loaf"],"ua":["випічка","банан","кекс"]}'::jsonb)
