values
  ('tvorozhnaya-zapekanka', 'dessert', true, null, 50, 200, 6, 'easy',
   '{"ru":"Творожная запеканка как в детстве","en":"Cottage-cheese bake","ua":"Сирна запіканка як у дитинстві"}'::jsonb,
   '{"ru":"Нежная творожная запеканка с ванилью — пышная, воздушная и не резиновая. Отличный ПП-завтрак или десерт с ложкой сметаны или ягод.","en":"A tender vanilla cottage-cheese bake — fluffy, airy and never rubbery. A great healthy breakfast or dessert with a spoon of sour cream or berries.","ua":"Ніжна сирна запіканка з ваніллю — пишна, повітряна й не гумова. Чудовий ПХ-сніданок або десерт із ложкою сметани чи ягодами."}'::jsonb,
   '{"ru":["Творог — 500 г","Яйца — 3 шт.","Манная крупа — 3 ст. л.","Сахар — 60 г","Сметана — 2 ст. л.","Ванильный сахар — 1 ч. л.","Щепотка соли"],"en":["Cottage cheese — 500 g","Eggs — 3","Semolina — 3 tbsp","Sugar — 60 g","Sour cream — 2 tbsp","Vanilla sugar — 1 tsp","A pinch of salt"],"ua":["Сир кисломолочний — 500 г","Яйця — 3 шт.","Манна крупа — 3 ст. л.","Цукор — 60 г","Сметана — 2 ст. л.","Ванільний цукор — 1 ч. л.","Дрібка солі"]}'::jsonb,
   '{"ru":["Разотрите творог с желтками, сахаром, сметаной и манкой.","Дайте массе постоять 15 минут, чтобы манка набухла.","Взбейте белки со щепоткой соли до пиков и аккуратно вмешайте.","Выложите в смазанную форму и разровняйте.","Выпекайте при 180 °C 35–40 минут; дайте остыть в форме, чтобы не осела."],"en":["Blend the cottage cheese with yolks, sugar, sour cream and semolina.","Let it rest 15 minutes so the semolina swells.","Whip the whites with a pinch of salt to peaks and fold in gently.","Spread into a greased dish and level the top.","Bake at 180 °C for 35–40 minutes; cool in the dish so it doesn''t sink."],"ua":["Розітріть сир із жовтками, цукром, сметаною й манкою.","Дайте масі постояти 15 хвилин, щоб манка набубнявіла.","Збийте білки з дрібкою солі до піків і обережно вмішайте.","Викладіть у змащену форму й розрівняйте.","Випікайте за 180 °C 35–40 хвилин; дайте охолонути у формі, щоб не осіла."]}'::jsonb,
   '{"ru":["ПП","десерт","творог","завтрак"],"en":["healthy","dessert","cottage cheese","breakfast"],"ua":["ПХ","десерт","сир","сніданок"]}'::jsonb)
