  ('sharlotka-s-yablokami', 'baking', false, null, 55, 240, 8, 'easy',
   '{"ru":"Шарлотка с яблоками","en":"Apple charlotte sponge","ua":"Шарлотка з яблуками"}'::jsonb,
   '{"ru":"Пышный бисквит с сочными яблоками — самый простой яблочный пирог, который получается всегда. Всего пять продуктов и никакого миксера-виртуоза.","en":"An airy sponge packed with juicy apples — the simplest apple cake that always works. Just five ingredients and no fancy mixer needed.","ua":"Пишний бісквіт із соковитими яблуками — найпростіший яблучний пиріг, що виходить завжди. Лише п''ять продуктів і жодного міксера-віртуоза."}'::jsonb,
   '{"ru":["Яблоки — 4 шт.","Яйца — 4 шт.","Сахар — 180 г","Мука — 180 г","Ванильный сахар — 1 ч. л.","Щепотка соли"],"en":["Apples — 4","Eggs — 4","Sugar — 180 g","Flour — 180 g","Vanilla sugar — 1 tsp","A pinch of salt"],"ua":["Яблука — 4 шт.","Яйця — 4 шт.","Цукор — 180 г","Борошно — 180 г","Ванільний цукор — 1 ч. л.","Дрібка солі"]}'::jsonb,
   '{"ru":["Взбейте яйца с сахаром и солью до пышной светлой массы 5–7 минут.","Аккуратно вмешайте просеянную муку, сохраняя воздушность.","Нарежьте яблоки дольками и выложите в форму.","Залейте тестом и распределите равномерно.","Выпекайте при 180 °C 35–40 минут до сухой шпажки; не открывайте духовку первые 25 минут."],"en":["Whip the eggs with sugar and salt to a pale, fluffy mass for 5–7 minutes.","Gently fold in the sifted flour, keeping the air in.","Slice the apples and arrange in the tin.","Pour over the batter and spread evenly.","Bake at 180 °C for 35–40 minutes until a skewer is clean; don''t open the oven for the first 25 minutes."],"ua":["Збийте яйця з цукром і сіллю до пишної світлої маси 5–7 хвилин.","Обережно вмішайте просіяне борошно, зберігаючи повітряність.","Наріжте яблука дольками й викладіть у форму.","Залийте тістом і розподіліть рівномірно.","Випікайте за 180 °C 35–40 хвилин до сухої шпажки; не відкривайте духовку перші 25 хвилин."]}'::jsonb,
   '{"ru":["выпечка","яблоки","пирог"],"en":["baking","apples","cake"],"ua":["випічка","яблука","пиріг"]}'::jsonb)
